pub fn metadata() -> &'static GrammarMetadata {
    &GRAMMAR_METADATA
}

pub fn rule_names() -> &'static [&'static str] {
    GRAMMAR_METADATA.rule_names()
}

fn parser_semantics() -> &'static antlr4_runtime::ParserSemantics {
    static SEMANTICS_CELL: OnceLock<antlr4_runtime::ParserSemantics> = OnceLock::new();
    SEMANTICS_CELL.get_or_init(|| {
        let mut ir = antlr4_runtime::semir::SemIr::new();
        let mut predicates = Vec::new();
        let __expr = ir.expr(antlr4_runtime::semir::PExpr::Hook(antlr4_runtime::semir::HookId::new(0)));
        predicates.push(antlr4_runtime::ParserSemanticPredicate { rule_index: 2, pred_index: 0, expr: __expr, failure_message: None });
        let __expr = ir.expr(antlr4_runtime::semir::PExpr::Hook(antlr4_runtime::semir::HookId::new(0)));
        predicates.push(antlr4_runtime::ParserSemanticPredicate { rule_index: 2, pred_index: 1, expr: __expr, failure_message: None });
        let __expr = ir.expr(antlr4_runtime::semir::PExpr::Hook(antlr4_runtime::semir::HookId::new(0)));
        predicates.push(antlr4_runtime::ParserSemanticPredicate { rule_index: 364, pred_index: 2, expr: __expr, failure_message: None });
        let __expr = ir.expr(antlr4_runtime::semir::PExpr::Hook(antlr4_runtime::semir::HookId::new(0)));
        predicates.push(antlr4_runtime::ParserSemanticPredicate { rule_index: 367, pred_index: 3, expr: __expr, failure_message: None });
        let __expr = ir.expr(antlr4_runtime::semir::PExpr::Hook(antlr4_runtime::semir::HookId::new(0)));
        predicates.push(antlr4_runtime::ParserSemanticPredicate { rule_index: 368, pred_index: 4, expr: __expr, failure_message: None });
        let __expr = ir.expr(antlr4_runtime::semir::PExpr::Hook(antlr4_runtime::semir::HookId::new(0)));
        predicates.push(antlr4_runtime::ParserSemanticPredicate { rule_index: 374, pred_index: 5, expr: __expr, failure_message: None });
        let __expr = ir.expr(antlr4_runtime::semir::PExpr::Hook(antlr4_runtime::semir::HookId::new(0)));
        predicates.push(antlr4_runtime::ParserSemanticPredicate { rule_index: 378, pred_index: 6, expr: __expr, failure_message: None });
        let __expr = ir.expr(antlr4_runtime::semir::PExpr::Hook(antlr4_runtime::semir::HookId::new(0)));
        predicates.push(antlr4_runtime::ParserSemanticPredicate { rule_index: 410, pred_index: 7, expr: __expr, failure_message: None });
        let __expr = ir.expr(antlr4_runtime::semir::PExpr::Hook(antlr4_runtime::semir::HookId::new(0)));
        predicates.push(antlr4_runtime::ParserSemanticPredicate { rule_index: 411, pred_index: 8, expr: __expr, failure_message: None });
        let __expr = ir.expr(antlr4_runtime::semir::PExpr::Hook(antlr4_runtime::semir::HookId::new(0)));
        predicates.push(antlr4_runtime::ParserSemanticPredicate { rule_index: 423, pred_index: 9, expr: __expr, failure_message: None });
        let __expr = ir.expr(antlr4_runtime::semir::PExpr::Hook(antlr4_runtime::semir::HookId::new(0)));
        predicates.push(antlr4_runtime::ParserSemanticPredicate { rule_index: 700, pred_index: 11, expr: __expr, failure_message: None });
        let __expr = ir.expr(antlr4_runtime::semir::PExpr::Hook(antlr4_runtime::semir::HookId::new(0)));
        predicates.push(antlr4_runtime::ParserSemanticPredicate { rule_index: 839, pred_index: 12, expr: __expr, failure_message: None });
        let __expr = ir.expr(antlr4_runtime::semir::PExpr::Hook(antlr4_runtime::semir::HookId::new(0)));
        predicates.push(antlr4_runtime::ParserSemanticPredicate { rule_index: 965, pred_index: 13, expr: __expr, failure_message: None });
        let __expr = ir.expr(antlr4_runtime::semir::PExpr::Hook(antlr4_runtime::semir::HookId::new(0)));
        predicates.push(antlr4_runtime::ParserSemanticPredicate { rule_index: 1040, pred_index: 14, expr: __expr, failure_message: None });
        let __expr = ir.expr(antlr4_runtime::semir::PExpr::Hook(antlr4_runtime::semir::HookId::new(0)));
        predicates.push(antlr4_runtime::ParserSemanticPredicate { rule_index: 1066, pred_index: 25, expr: __expr, failure_message: None });
        let __expr = ir.expr(antlr4_runtime::semir::PExpr::Hook(antlr4_runtime::semir::HookId::new(0)));
        predicates.push(antlr4_runtime::ParserSemanticPredicate { rule_index: 1082, pred_index: 26, expr: __expr, failure_message: None });

        let actions = Vec::new();
        antlr4_runtime::ParserSemantics { ir, predicates, actions }
    })
}

pub trait PlSqlParserHooks: Sized {
    fn is_last_sql_solidus<L>(&mut self, ctx: &mut antlr4_runtime::ParserSemCtx<'_, L>) -> bool
    where
        L: TokenSource;

    fn is_not_numeric_function<L>(&mut self, ctx: &mut antlr4_runtime::ParserSemCtx<'_, L>) -> bool
    where
        L: TokenSource;

    fn is_not_start_of_join<L>(&mut self, ctx: &mut antlr4_runtime::ParserSemCtx<'_, L>) -> bool
    where
        L: TokenSource;

    fn is_solidus_separator<L>(&mut self, ctx: &mut antlr4_runtime::ParserSemCtx<'_, L>) -> bool
    where
        L: TokenSource;

    fn is_version_10<L>(&mut self, ctx: &mut antlr4_runtime::ParserSemCtx<'_, L>) -> bool
    where
        L: TokenSource;

    fn is_version_11<L>(&mut self, ctx: &mut antlr4_runtime::ParserSemCtx<'_, L>) -> bool
    where
        L: TokenSource;

    fn is_version_12<L>(&mut self, ctx: &mut antlr4_runtime::ParserSemCtx<'_, L>) -> bool
    where
        L: TokenSource;

    fn set_last_unit_plsql<L>(&mut self, ctx: &mut antlr4_runtime::ParserSemCtx<'_, L>)
    where
        L: TokenSource;

    fn set_last_unit_sql<L>(&mut self, ctx: &mut antlr4_runtime::ParserSemCtx<'_, L>)
    where
        L: TokenSource;

    /// Handles a committed parser action routed to the typed hook. Return
    /// `true` when the action is handled so it satisfies a `hook`/`error`
    /// unknown-semantic policy; the default no-op returns `false` (unhandled),
    /// which fails loud under those policies.
    fn custom_action<L>(&mut self, _ctx: &mut antlr4_runtime::ParserSemCtx<'_, L>, _action: antlr4_runtime::ParserAction) -> bool
    where
        L: TokenSource,
    {
        false
    }
}

#[derive(Clone, Copy, Debug, Default)]
pub struct PlSqlParserTypedHooks<T>(pub T);

impl<T> PlSqlParserTypedHooks<T> {
    pub const fn new(inner: T) -> Self { Self(inner) }
}

impl<T> antlr4_runtime::SemanticHooks for PlSqlParserTypedHooks<T>
where
    T: PlSqlParserHooks,
{
    fn sempred<L>(&mut self, ctx: &mut antlr4_runtime::ParserSemCtx<'_, L>, rule_index: usize, pred_index: usize) -> Option<bool>
    where
        L: TokenSource,
    {
        match (rule_index, pred_index) {
            (2, 0) => Some(self.0.is_solidus_separator(ctx)),
            (2, 1) => Some(self.0.is_last_sql_solidus(ctx)),
            (364, 2) => Some(self.0.is_version_12(ctx)),
            (367, 3) => Some(self.0.is_version_12(ctx)),
            (368, 4) => Some(self.0.is_version_12(ctx)),
            (374, 5) => Some(self.0.is_version_12(ctx)),
            (378, 6) => Some(self.0.is_version_12(ctx)),
            (410, 7) => Some(self.0.is_version_12(ctx)),
            (411, 8) => Some(self.0.is_version_12(ctx)),
            (423, 9) => Some(self.0.is_version_12(ctx)),
            (700, 11) => Some(self.0.is_version_10(ctx)),
            (839, 12) => Some(self.0.is_version_12(ctx)),
            (965, 13) => Some(self.0.is_not_start_of_join(ctx)),
            (1040, 14) => Some(self.0.is_version_11(ctx)),
            (1066, 25) => Some(self.0.is_not_numeric_function(ctx)),
            (1082, 26) => Some(self.0.is_not_numeric_function(ctx)),
            _ => None,
        }
    }

    fn action<L>(&mut self, ctx: &mut antlr4_runtime::ParserSemCtx<'_, L>, action: antlr4_runtime::ParserAction) -> bool
    where
        L: TokenSource,
    {
        match (action.rule_index(), action.action_index()) {
            (1, Some(0)) => { self.0.set_last_unit_plsql(ctx); true },
            (1, Some(1)) => { self.0.set_last_unit_sql(ctx); true },
            (1, Some(2)) => { self.0.set_last_unit_sql(ctx); true },
            _ => self.0.custom_action(ctx, action),
        }
    }
}


/// Marker carried by generated contexts whose required-child
/// invariants were checked after a syntax-clean parse, and grammar brand of
/// this module's validated tree and rule-node types.
///
/// This marker stays module-local (unlike the runtime-owned support items)
/// so rustc can prove it never implements the runtime's
/// `__RecoveryContextState`, keeping the recovery-oriented and validated
/// accessor impls coherent — and so the runtime's branded validated types
/// stay nominally distinct per grammar.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct ValidatedTreeContext {
    __private: (),
}

/// A completed, syntax-clean parse tree whose generated child cardinalities
/// have been structurally validated.
///
/// Alias of the runtime's grammar-agnostic `antlr4_runtime::ValidatedTree`
/// branded with this module's [`ValidatedTreeContext`] marker, so validated
/// trees of different grammars remain distinct types.
pub type PlSqlValidatedTree = antlr4_runtime::ValidatedTree<ValidatedTreeContext>;

/// A rule node borrowed from a [`PlSqlValidatedTree`].
///
/// Alias of the runtime's `antlr4_runtime::ValidatedRuleNode` branded with
/// this module's [`ValidatedTreeContext`] marker.
pub type ValidatedRuleNode<'a> = antlr4_runtime::ValidatedRuleNode<'a, ValidatedTreeContext>;

pub use antlr4_runtime::FromValidatedRuleNode;

/// Failure to recognize or validate a strict generated parse.
///
/// Alias of the grammar-agnostic `antlr4_runtime::ValidationError`; unlike
/// the branded tree types, the validation errors of every generated parser
/// are deliberately one shared type.
pub type PlSqlValidationError = antlr4_runtime::ValidationError;

